enum class GamePiece(val points: Int) {
    CONE(3),
    CUBE(4),
    NONE(0)
}

fun totalPoints(pieces: List<GamePiece>): Int {
    var total = 0
    for (piece in pieces) {
        total += piece.points
    }
    return total
}

