import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testConePoints() {
        Assert.assertEquals(3, GamePiece.CONE.points)
    }

    @Test
    fun testCubePoints() {
        Assert.assertEquals(4, GamePiece.CUBE.points)
    }

    @Test
    fun testNonePoints() {
        Assert.assertEquals(0, GamePiece.NONE.points)
    }

    @Test
    fun testTotalPointsMixed() {
        val pieces = listOf(GamePiece.CONE, GamePiece.CUBE, GamePiece.CONE)
        Assert.assertEquals(10, totalPoints(pieces))
    }

    @Test
    fun testTotalPointsEmpty() {
        Assert.assertEquals(0, totalPoints(emptyList()))
    }

    @Test
    fun testTotalPointsWithNone() {
        val pieces = listOf(GamePiece.CONE, GamePiece.NONE, GamePiece.CUBE)
        Assert.assertEquals(7, totalPoints(pieces))
    }
}
